begin;
create temp table checks(label text);
create temp table fixture(k text primary key,v jsonb);
grant all on checks,fixture to authenticated;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',label;end if;insert into checks values(label);end$$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when insufficient_privilege then perform pg_temp.ok(true,label);return;end;raise exception 'Expected denial: %',label;end$$;
insert into auth.users(id,is_anonymous) values
 ('44000000-0000-4000-8000-000000000001',false),('44000000-0000-4000-8000-000000000002',false),
 ('44000000-0000-4000-8000-000000000003',true),('44000000-0000-4000-8000-000000000004',true);
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) values('44000000-0000-4000-8000-000000000010','44000000-0000-4000-8000-000000000001','7B',7,32,'demo');
insert into fixture values('state','{"schemaVersion":1,"mode":"opening","question":1,"taskEpoch":"44000000-0000-4000-8000-000000000090","groups":[]}');
select pg_temp.ok(pn_private.valid_public_state((select v from fixture where k='state')),'strict state accepted');
select pg_temp.ok(not pn_private.valid_public_state((select v||'{"name":"canary"}' from fixture where k='state')),'extra identity rejected at SQL sink');
select pg_temp.ok(not pn_private.valid_public_state((select v||'{"mode":null}' from fixture where k='state')),'null mode rejected');
select pg_temp.ok(not pn_private.valid_public_state((select v||'{"groups":[{"id":"44000000-0000-4000-8000-000000000099","label":"Segitiga Biru","attendanceNumbers":[7],"level":"D1"}]}' from fixture where k='state')),'board level rejected at SQL sink');
set local role authenticated;
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000003","is_anonymous":true}';
insert into fixture select 'pair',public.presentation_action('create',jsonb_build_object('codeHash',repeat('a',64),'ipHash','fixture'));
select pg_temp.ok((select v?'id' from fixture where k='pair'),'board creates challenge');
select pg_temp.denied('select * from pn_private.pairings','cannot read hashes/membership directly');
select pg_temp.ok(public.presentation_action('claim',jsonb_build_object('codeHash',repeat('a',64)))->>'error'='FORBIDDEN','board cannot claim as teacher');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok(public.presentation_action('claim',jsonb_build_object('codeHash',repeat('a',64),'classId','44000000-0000-4000-8000-000000000010','sessionId','44000000-0000-4000-8000-000000000011','payload',(select v from fixture where k='state')))->>'error'='FORBIDDEN','other teacher cannot bind foreign class');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000001","is_anonymous":false}';
insert into fixture select 'snapshot',public.presentation_action('claim',jsonb_build_object('codeHash',repeat('a',64),'classId','44000000-0000-4000-8000-000000000010','sessionId','44000000-0000-4000-8000-000000000011','payload',(select v from fixture where k='state')));
select pg_temp.ok((select v->'envelope'->>'revision'='1' and v->>'ackRevision'='0' from fixture where k='snapshot'),'claim waits for ACK');
insert into fixture select 'ref',jsonb_build_object('presentationId',v->'envelope'->'presentationId','channelEpoch',v->'envelope'->'channelEpoch','commandId',v->'envelope'->'commandId') from fixture where k='snapshot';
select pg_temp.ok(public.presentation_action('claim',jsonb_build_object('codeHash',repeat('a',64),'classId','44000000-0000-4000-8000-000000000010','sessionId','44000000-0000-4000-8000-000000000011','payload',(select v from fixture where k='state')))->>'error'='NOT_FOUND','pairing single use');
select pg_temp.ok(public.presentation_action('ack',(select v||'{"appliedRevision":1}' from fixture where k='ref'))->>'error'='FORBIDDEN','teacher cannot spoof board ACK');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000004","is_anonymous":true}';
select pg_temp.ok(public.presentation_action('snapshot',(select v from fixture where k='ref'))->>'error'='FORBIDDEN','unpaired board denied snapshot');
select pg_temp.ok(not public.presentation_topic_allowed((select 'pn:state:'||(v->>'presentationId')||':'||(v->>'channelEpoch') from fixture where k='ref')),'unpaired board denied topic');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok(public.presentation_topic_allowed((select 'pn:state:'||(v->>'presentationId')||':'||(v->>'channelEpoch') from fixture where k='ref')),'paired board joins exact private topic');
select pg_temp.ok(not public.presentation_topic_allowed('students:*'),'student topic denied');
select pg_temp.ok(not public.presentation_topic_allowed('pn:state:unknown'),'unknown topic denied');
select set_config('realtime.topic',(select 'pn:state:'||(v->>'presentationId')||':'||(v->>'channelEpoch') from fixture where k='ref'),true);
select pg_temp.ok((select count(*)>=1 from realtime.messages),'Realtime SELECT policy allows member');
select pg_temp.denied($q$insert into realtime.messages(topic,extension,payload) values('spoof','broadcast','{}')$q$,'client state broadcast INSERT denied');
select pg_temp.ok(public.presentation_action('ack',(select v||'{"appliedRevision":2}' from fixture where k='ref'))->>'error'='CONFLICT','ACK wrong revision rejected');
select pg_temp.ok(public.presentation_action('ack',(select v||'{"appliedRevision":1}' from fixture where k='ref'))->>'ok'='true','board ACK applied');
select pg_temp.ok(public.presentation_action('publish',(select v||jsonb_build_object('baseRevision',1,'payload',(select v from fixture where k='state')) from fixture where k='ref'))->>'error'='FORBIDDEN','board cannot publish teacher state');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000001","is_anonymous":false}';
insert into fixture select 'command',v||jsonb_build_object('commandId','44000000-0000-4000-8000-000000000091','baseRevision',1,'payload',(select v||'{"mode":"station"}' from fixture where k='state')) from fixture where k='ref';
select pg_temp.ok(public.presentation_action('publish',(select v from fixture where k='command'))->'envelope'->>'revision'='2','owner publishes revision 2');
select pg_temp.ok(public.presentation_action('publish',(select v from fixture where k='command'))->'envelope'->>'revision'='2','command retry idempotent');
select pg_temp.ok(public.presentation_action('publish',(select v||jsonb_build_object('commandId','44000000-0000-4000-8000-000000000092') from fixture where k='command'))->>'error'='CONFLICT','stale revision rejected');
select pg_temp.ok(public.presentation_action('publish',(select v||jsonb_build_object('channelEpoch','44000000-0000-4000-8000-000000000093') from fixture where k='command'))->>'error'='CONFLICT','old epoch rejected');
select pg_temp.ok(public.presentation_action('publish',(select v||jsonb_build_object('baseRevision',2,'commandId','44000000-0000-4000-8000-000000000094') from fixture where k='command'))->'envelope'->>'revision'='3','later command revision 3');
select pg_temp.ok(public.presentation_action('publish',(select v from fixture where k='command'))->'envelope'->>'revision'='3','old duplicate returns canonical snapshot without applying again');
select pg_temp.ok(public.presentation_action('publish',(select v||'{"baseRevision":3}' from fixture where k='command'))->>'error'='CONFLICT','old command identity cannot be reused with new revision');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok(public.presentation_action('snapshot',(select v from fixture where k='ref'))->>'error'='FORBIDDEN','cross tenant snapshot rejected');
select pg_temp.ok(public.presentation_action('revoke',(select v from fixture where k='ref'))->>'error'='FORBIDDEN','cross tenant revoke rejected');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok(public.presentation_action('revoke',(select v from fixture where k='ref'))->>'ok'='true','owner revoke');
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok(public.presentation_action('snapshot',(select v from fixture where k='ref'))->>'error'='FORBIDDEN','revoked board denied recovery');
select pg_temp.ok(not public.presentation_topic_allowed((select 'pn:state:'||(v->>'presentationId')||':'||(v->>'channelEpoch') from fixture where k='ref')),'revoked epoch topic denied');
insert into fixture select 'expired',public.presentation_action('create',jsonb_build_object('codeHash',repeat('b',64),'ipHash','fixture'));
reset role;
update pn_private.pairings set expires_at=now()-interval '1 second' where id=(select (v->>'id')::uuid from fixture where k='expired');
set local role authenticated;
set local request.jwt.claims='{"sub":"44000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok(public.presentation_action('claim',jsonb_build_object('codeHash',repeat('b',64),'classId','44000000-0000-4000-8000-000000000010','sessionId','44000000-0000-4000-8000-000000000011','payload',(select v from fixture where k='state')))->>'error'='NOT_FOUND','expired code rejected');
select public.presentation_action('claim',jsonb_build_object('codeHash',repeat('f',64),'classId','44000000-0000-4000-8000-000000000010','sessionId','44000000-0000-4000-8000-000000000011','payload',(select v from fixture where k='state'))) from generate_series(1,2);
select pg_temp.ok(public.presentation_action('claim',jsonb_build_object('codeHash',repeat('f',64)))->>'error'='RATE_LIMITED','sixth claim rate limited in shared SQL');
reset role;
select 'PASS pairing/Realtime SQL assertions: '||count(*) from checks;
rollback;
